import os
import sys
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from convert import cm_to_inches  # noqa: E402


class Tests(unittest.TestCase):
    def test_ten_inches(self):
        self.assertEqual(cm_to_inches(25.4), 10.0)

    def test_waist(self):
        self.assertEqual(cm_to_inches(81), 31.9)


if __name__ == "__main__":
    unittest.main()
